<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, shallowRef, watch } from 'vue'
import { Aim, Close, Download, FullScreen, PictureFilled, RefreshRight, Search, Setting, UploadFilled, VideoCamera, ZoomIn, ZoomOut } from '@element-plus/icons-vue'
import { ElMessage, genFileId } from 'element-plus'
import type { UploadFile, UploadInstance, UploadProps, UploadRawFile } from 'element-plus'
import { analyzeMedia, getApiErrorMessage, getBackendHealth, isBackendConnectionError } from '../api/modelApi'
import type { AnalyzeMediaResponse, BackendHealth, DetectedObject, PromptMode } from '../api/modelApi'
import { createMaskCanvas, createMaskEdgeCanvas, decodeMask, drawMaskLayer, getContainSize } from '../utils/canvasUtil'
import type { RgbColor, Size } from '../utils/canvasUtil'

const COLORS: readonly RgbColor[] = [[66,133,244],[43,193,144],[242,165,62],[234,97,125],[151,114,235],[46,181,198],[205,102,184],[134,172,80]]
const COLOR_CSS = COLORS.map(([r,g,b]) => `rgb(${r}, ${g}, ${b})`)
const VIDEO_EXTENSIONS = ['.mp4','.avi','.mov','.mkv','.webm','.m4v']
const IMAGE_EXTENSIONS = ['.jpg','.jpeg','.png','.bmp','.webp','.tif','.tiff']
interface DisplayOptions { boxes:boolean; labels:boolean; confidence:boolean; details:boolean; maskFill:boolean; maskEdge:boolean; pose:boolean; hands:boolean }
interface FrameLayers { fill: HTMLCanvasElement[]; edge: HTMLCanvasElement[] }

const uploadRef = ref<UploadInstance>(); const viewportRef = ref<HTMLDivElement>(); const canvasRef = ref<HTMLCanvasElement>(); const videoRef = ref<HTMLVideoElement>()
const selectedFile = shallowRef<File|null>(null); const mediaCanvas = shallowRef<HTMLCanvasElement|null>(null); const videoUrl = ref('')
const imageSize = ref<Size>({width:0,height:0}); const baseCanvasSize = ref<Size>({width:0,height:0})
const response = shallowRef<AnalyzeMediaResponse|null>(null); const objects = ref<DetectedObject[]>([]); const frameLayers = shallowRef<FrameLayers[]>([]); const fillLayers = shallowRef<HTMLCanvasElement[]>([]); const edgeLayers = shallowRef<HTMLCanvasElement[]>([])
const activeVideoFrameIndex = ref(0); const selectedLabels = ref<string[]>([]); const selectedIndex = ref<number|null>(null); const promptMode = ref<PromptMode>('universal'); const textPrompt = ref('')
const loading = ref(false); const previewLoading = ref(false); const zoom = ref(1); const thumbnailUrl = ref(''); const backendOnline = ref(false); const backendHealth = shallowRef<BackendHealth|null>(null); const healthNotice = ref(''); const isPanning = ref(false); const analysisSeconds = ref(0); const panOffset = reactive({ x: 0, y: 0 }); const hoveredIndex = ref<number|null>(null); const hoverTip = reactive({x:0,y:0,visible:false})
const displayOptions = reactive<DisplayOptions>({boxes:true,labels:true,confidence:false,details:false,maskFill:false,maskEdge:false,pose:true,hands:true})
let requestController: AbortController|null = null; let resizeObserver: ResizeObserver|null = null; let healthTimer: number|null = null; let analysisTimer: number|null = null
let panStart: {x:number;y:number;left:number;top:number;moved:boolean}|null = null

const fileName = computed(() => selectedFile.value?.name ?? '')
const isVideo = computed(() => Boolean(selectedFile.value && (selectedFile.value.type.startsWith('video/') || VIDEO_EXTENSIONS.some((ext) => selectedFile.value!.name.toLowerCase().endsWith(ext)))))
const videoFrames = computed(() => response.value?.frames ?? [])
const activeObjects = computed(() => isVideo.value && videoFrames.value.length ? videoFrames.value[activeVideoFrameIndex.value]?.objects ?? [] : objects.value)
const activeLayers = computed<FrameLayers>(() => isVideo.value && frameLayers.value.length ? frameLayers.value[activeVideoFrameIndex.value] ?? {fill:[],edge:[]} : {fill:fillLayers.value,edge:edgeLayers.value})
const labels = computed(() => isVideo.value ? [...new Set(activeObjects.value.map((item) => item.label))] : (response.value?.labels.length ? response.value.labels : [...new Set(activeObjects.value.map((item) => item.label))]))
const visibleIndexes = computed(() => selectedIndex.value !== null && activeObjects.value[selectedIndex.value] ? [selectedIndex.value] : activeObjects.value.map((_,i) => i).filter((i) => selectedLabels.value.includes(activeObjects.value[i].label)))
const hoveredObject = computed(() => hoveredIndex.value === null ? null : activeObjects.value[hoveredIndex.value] ?? null)
// The button stays actionable while the health probe is catching up; runAnalysis
// gives a precise service/model message instead of silently disabling the task.
const canAnalyze = computed(() => Boolean(selectedFile.value && mediaCanvas.value && !loading.value && (promptMode.value === 'universal' || textPrompt.value.trim())))
const runtimeState = computed(() => !backendOnline.value ? 'offline' : backendHealth.value?.status === 'ready' ? 'ready' : backendHealth.value?.status === 'model_error' ? 'error' : 'loading')
const runtimeLabel = computed(() => { if (!backendOnline.value) return '推理服务离线'; if (backendHealth.value?.status === 'model_error') return '模型加载失败'; const progress = backendHealth.value?.model_progress; if (backendHealth.value?.status !== 'ready') return progress ? `模型加载中 ${progress.percent}%` : '模型加载中'; const assets = backendHealth.value?.model_assets ?? backendHealth.value?.capabilities ?? {}; const missing = Object.values(assets).filter((item) => !item.available).length; return missing ? `${backendHealth.value.device.startsWith('GPU') ? 'Arc GPU' : 'CPU'} 已就绪 · ${missing}项能力待补齐` : (backendHealth.value.device.startsWith('GPU') ? 'OpenVINO Arc GPU 已就绪' : 'CPU 推理已就绪') })
const stageSpaceStyle = computed(() => ({width:`max(100%, ${Math.ceil(baseCanvasSize.value.width * zoom.value + 80)}px)`,height:`max(100%, ${Math.ceil(baseCanvasSize.value.height * zoom.value + 80)}px)`}))
const stageStyle = computed(() => ({width:`${baseCanvasSize.value.width * zoom.value}px`,height:`${baseCanvasSize.value.height * zoom.value}px`,transform:`translate(${panOffset.x}px, ${panOffset.y}px)`}))
const mediaStyle = computed(() => ({width:`${baseCanvasSize.value.width}px`,height:`${baseCanvasSize.value.height}px`,transform:`scale(${zoom.value})`}))
const frameLabel = computed(() => videoFrames.value.length ? `关键帧 ${activeVideoFrameIndex.value + 1}/${videoFrames.value.length} · ${videoFrames.value[activeVideoFrameIndex.value].timestamp.toFixed(2)}s` : '')
const loadingDetail = computed(() => analysisSeconds.value < 2 ? '正在提交本地分析任务' : isVideo.value ? `正在分析视频关键帧，已等待 ${analysisSeconds.value}s` : `本地视觉模型推理中，已等待 ${analysisSeconds.value}s`)

function validate(file: File) { const ext = file.name.slice(file.name.lastIndexOf('.')).toLowerCase(); const video = file.type.startsWith('video/') || VIDEO_EXTENSIONS.includes(ext); if (!(video || file.type.startsWith('image/') || IMAGE_EXTENSIONS.includes(ext))) return false; if (file.size > (video ? 100 : 20) * 1024 * 1024) { ElMessage.error(video ? '视频文件不能超过 100 MB。' : '图片文件不能超过 20 MB。'); return false } return true }
function thumbnail(source: HTMLCanvasElement) { const scale = Math.min(1,460/Math.max(source.width,source.height)); const out=document.createElement('canvas'); out.width=Math.max(1,Math.round(source.width*scale)); out.height=Math.max(1,Math.round(source.height*scale)); out.getContext('2d')?.drawImage(source,0,0,out.width,out.height); return out.toDataURL('image/jpeg',.86) }
function videoFrame(file: File): Promise<HTMLCanvasElement> { return new Promise((resolve,reject) => { const url=URL.createObjectURL(file); const v=document.createElement('video'); v.muted=true;v.playsInline=true;v.preload='auto'; const clean=()=>{URL.revokeObjectURL(url);v.removeAttribute('src');v.load()}; v.onerror=()=>{clean();reject(new Error('视频解析失败，请检查文件编码。'))};v.onloadeddata=()=>{try{const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d')?.drawImage(v,0,0);clean();resolve(c)}catch(e){clean();reject(e)}};v.src=url;v.load()}) }
async function fileCanvas(file: File) { if (file.type.startsWith('video/') || VIDEO_EXTENSIONS.some((e)=>file.name.toLowerCase().endsWith(e))) return videoFrame(file); const bitmap=await createImageBitmap(file); const c=document.createElement('canvas');c.width=bitmap.width;c.height=bitmap.height;c.getContext('2d')?.drawImage(bitmap,0,0);bitmap.close();return c }
function revokeVideo() { if(videoUrl.value) URL.revokeObjectURL(videoUrl.value); videoUrl.value='' }
function reset() { requestController?.abort(); objects.value=[];response.value=null;fillLayers.value=[];edgeLayers.value=[];frameLayers.value=[];selectedLabels.value=[];selectedIndex.value=null;hoveredIndex.value=null;hoverTip.visible=false;activeVideoFrameIndex.value=0 }
async function selectFile(file: File) { if(!validate(file)){ElMessage.error('请选择受支持的图片或视频文件。');uploadRef.value?.clearFiles();return} previewLoading.value=true;reset();revokeVideo();selectedFile.value=file;if(isVideo.value)videoUrl.value=URL.createObjectURL(file);try{const c=await fileCanvas(file);mediaCanvas.value=c;thumbnailUrl.value=thumbnail(c);imageSize.value={width:c.width,height:c.height};await nextTick();updateSize()}catch(e){clearMedia();ElMessage.error(e instanceof Error?e.message:'媒体文件解析失败。')}finally{previewLoading.value=false} }
const onChange: UploadProps['onChange'] = async (f: UploadFile) => { if(f.raw) await selectFile(f.raw) }
const onExceed: UploadProps['onExceed'] = (files) => { uploadRef.value?.clearFiles(); const f=files[0] as UploadRawFile;f.uid=genFileId();uploadRef.value?.handleStart(f) }
function clearMedia(){videoRef.value?.pause();uploadRef.value?.clearFiles();reset();revokeVideo();selectedFile.value=null;mediaCanvas.value=null;thumbnailUrl.value='';imageSize.value={width:0,height:0};baseCanvasSize.value={width:0,height:0};zoom.value=1}
function changeMode(mode: PromptMode){if(loading.value)return;promptMode.value=mode;textPrompt.value='';reset()}
function layers(items: DetectedObject[]): FrameLayers { return {fill:items.map((o,i)=>createMaskCanvas(decodeMask(o.mask,o.mask_rle,o.mask_size),COLORS[i%COLORS.length])),edge:items.map((o,i)=>createMaskEdgeCanvas(decodeMask(o.mask,o.mask_rle,o.mask_size),COLORS[i%COLORS.length]))} }
async function runAnalysis(){ if(!backendOnline.value){await health();if(!backendOnline.value){ElMessage.error('后端服务未启动，请运行 start-backend.ps1。');return}};if(backendHealth.value?.status!=='ready'){ElMessage.warning('模型正在加载或不可用，请稍候再试。');return};if(!selectedFile.value || (promptMode.value!=='universal'&&!textPrompt.value.trim())){ElMessage.warning('请先选择媒体并填写提示。');return};loading.value=true;analysisSeconds.value=0;analysisTimer=window.setInterval(()=>{analysisSeconds.value+=1},1000);selectedIndex.value=null;requestController=new AbortController();try{const result=await analyzeMedia(selectedFile.value,textPrompt.value.trim(),promptMode.value,requestController.signal);response.value=result;objects.value=result.objects;selectedLabels.value=[...result.labels];activeVideoFrameIndex.value=0;if(result.media_type==='video'&&result.frames.length){frameLayers.value=result.frames.map((f)=>layers(f.objects));fillLayers.value=[];edgeLayers.value=[]}else{const l=layers(result.objects);fillLayers.value=l.fill;edgeLayers.value=l.edge;frameLayers.value=[]}draw();ElMessage.success(`分析完成，${result.media_type==='video'?'已分析 '+result.frames.length+' 个关键帧，':'共'}识别 ${result.objects.length} 个首帧目标。`)}catch(e){ElMessage.error(getApiErrorMessage(e))}finally{loading.value=false;requestController=null;if(analysisTimer!==null){window.clearInterval(analysisTimer);analysisTimer=null}} }
function cancelAnalysis(){requestController?.abort();requestController=null;loading.value=false;if(analysisTimer!==null){window.clearInterval(analysisTimer);analysisTimer=null}ElMessage.info('已取消等待当前推理结果。')}
async function health(){
  try {
    const result = await getBackendHealth()
    if (!result || !result.status || !['ready', 'loading', 'model_error', 'not_loaded'].includes(result.status)) {
      throw new Error('健康接口返回格式异常')
    }
    backendHealth.value = result
    backendOnline.value = true
    // ready 和正常 loading 都不是错误；只有后端明确报告 model_error 才显示异常提示。
    healthNotice.value = result.status === 'model_error'
      ? '后端服务已启动，但服务异常，请查看后端控制台日志'
      : ''
  } catch (error) {
    backendHealth.value = null
    backendOnline.value = false
    healthNotice.value = isBackendConnectionError(error)
      ? '后端服务未启动，请运行 start-backend.ps1'
      : '后端服务已启动，但服务异常，请查看后端控制台日志'
  }
}
function updateSize(){if(!viewportRef.value||!mediaCanvas.value)return;baseCanvasSize.value=getContainSize(imageSize.value,{width:viewportRef.value.clientWidth,height:viewportRef.value.clientHeight},72);nextTick(draw)}
function draw(){const c=canvasRef.value,t=baseCanvasSize.value;if(!c||!t.width)return;const d=Math.min(devicePixelRatio||1,2);c.width=t.width*d;c.height=t.height*d;const ctx=c.getContext('2d');if(!ctx)return;ctx.setTransform(d,0,0,d,0,0);drawScene(ctx,t,!isVideo.value)}
function drawScene(ctx: CanvasRenderingContext2D,t: Size,base=true){if(!mediaCanvas.value)return;ctx.clearRect(0,0,t.width,t.height);if(base){const source=isVideo.value&&videoRef.value&&videoRef.value.readyState>=2?videoRef.value:mediaCanvas.value;ctx.drawImage(source,0,0,t.width,t.height)}const indexes=visibleIndexes.value;const l=activeLayers.value;indexes.forEach((i)=>{if(displayOptions.maskFill&&l.fill[i])drawMaskLayer(ctx,l.fill[i],t,i===selectedIndex.value);if(displayOptions.maskEdge&&l.edge[i])drawMaskLayer(ctx,l.edge[i],t,i===selectedIndex.value,1);if(displayOptions.boxes||displayOptions.labels||displayOptions.confidence||displayOptions.details)drawBox(ctx,activeObjects.value[i],i,t);if(displayOptions.pose)drawPose(ctx,activeObjects.value[i],i,t);if(displayOptions.hands)drawHandPose(ctx,activeObjects.value[i],i,t)})}
function wrapCanvasText(ctx:CanvasRenderingContext2D,text:string,maxWidth:number){const lines:string[]=[];let current='';for(const char of text){const next=current+char;if(current&&ctx.measureText(next).width>maxWidth){lines.push(current);current=char}else current=next}if(current)lines.push(current);return lines}
function drawBox(ctx: CanvasRenderingContext2D,o: DetectedObject,i:number,t:Size){const sx=t.width/imageSize.value.width,sy=t.height/imageSize.value.height,x=o.bbox[0]*sx,y=o.bbox[1]*sy,w=(o.bbox[2]-o.bbox[0])*sx,h=(o.bbox[3]-o.bbox[1])*sy,color=COLOR_CSS[i%COLOR_CSS.length],active=selectedIndex.value===i||hoveredIndex.value===i;ctx.save();if(displayOptions.boxes){ctx.strokeStyle=color;ctx.lineWidth=active?4:2;ctx.strokeRect(x,y,w,h)}const parts=[];if(displayOptions.labels||displayOptions.details)parts.push(o.label);if(displayOptions.confidence)parts.push(`${Math.round(o.score*100)}%`);if(parts.length){ctx.font='600 12px Arial';const text=parts.join('  '),lw=ctx.measureText(text).width+16,lh=24,lx=Math.min(Math.max(0,x),Math.max(0,t.width-lw)),ly=y>=lh?y-lh:y;ctx.fillStyle=color;ctx.fillRect(lx,ly,lw,lh);ctx.fillStyle='#fff';ctx.textBaseline='middle';ctx.fillText(text,lx+8,ly+lh/2)}if(displayOptions.details&&(o.description||o.ocr_text||o.caption)){ctx.font='11px Arial';const detail=[o.description,o.caption?`描述：${o.caption}`:'',o.ocr_text?`文字：${o.ocr_text}`:''].filter(Boolean).flatMap((line)=>wrapCanvasText(ctx,line,Math.max(72,Math.min(w-12,260)))).slice(0,4);const lineHeight=15,detailWidth=Math.max(92,Math.min(w,280)),detailHeight=detail.length*lineHeight+8;if(detail.length&&h>=detailHeight+8){ctx.fillStyle='rgba(10,14,20,.82)';ctx.fillRect(x+2,y+2,detailWidth,detailHeight);ctx.fillStyle='#f1f5fa';ctx.textBaseline='top';detail.forEach((line,index)=>ctx.fillText(line,x+7,y+6+index*lineHeight))}}ctx.restore()}
const COCO_SKELETON: readonly [number,number][] = [[5,7],[7,9],[6,8],[8,10],[5,6],[5,11],[6,12],[11,12],[11,13],[13,15],[12,14],[14,16],[0,1],[0,2],[1,3],[2,4],[0,5],[0,6]]
function drawPose(ctx: CanvasRenderingContext2D,o: DetectedObject,i:number,t:Size){if(o.label.toLowerCase()!=='person'||o.keypoints.length!==17)return;const sx=t.width/imageSize.value.width,sy=t.height/imageSize.value.height,color=COLOR_CSS[i%COLOR_CSS.length];const point=(index:number)=>o.keypoints[index];ctx.save();ctx.strokeStyle=color;ctx.fillStyle='#fff';ctx.lineWidth=selectedIndex.value===i?3:2;COCO_SKELETON.forEach(([a,b])=>{const pa=point(a),pb=point(b);if(pa.score<.2||pb.score<.2)return;ctx.beginPath();ctx.moveTo(pa.x*sx,pa.y*sy);ctx.lineTo(pb.x*sx,pb.y*sy);ctx.stroke()});o.keypoints.forEach((p)=>{if(p.score<.2)return;ctx.beginPath();ctx.arc(p.x*sx,p.y*sy,3,0,Math.PI*2);ctx.fill();ctx.stroke()});ctx.restore()}
function drawHandPose(ctx: CanvasRenderingContext2D,o: DetectedObject,i:number,t:Size){if(!o.hand_keypoints?.length)return;const sx=t.width/imageSize.value.width,sy=t.height/imageSize.value.height,color=COLOR_CSS[i%COLOR_CSS.length];const fingers:readonly [number,number][][]=[[[0,1],[1,2],[2,3],[3,4]],[[0,5],[5,6],[6,7],[7,8]],[[0,9],[9,10],[10,11],[11,12]],[[0,13],[13,14],[14,15],[15,16]],[[0,17],[17,18],[18,19],[19,20]]];ctx.save();ctx.strokeStyle=color;ctx.fillStyle='#fff';ctx.lineWidth=selectedIndex.value===i?3:2;o.hand_keypoints.forEach((hand)=>{if(hand.length!==21)return;fingers.forEach((finger)=>finger.forEach(([a,b])=>{const pa=hand[a],pb=hand[b];if(pa.score<.2||pb.score<.2)return;ctx.beginPath();ctx.moveTo(pa.x*sx,pa.y*sy);ctx.lineTo(pb.x*sx,pb.y*sy);ctx.stroke()}));hand.forEach((p)=>{if(p.score<.2)return;ctx.beginPath();ctx.arc(p.x*sx,p.y*sy,2.5,0,Math.PI*2);ctx.fill();ctx.stroke()})});ctx.restore()}
function syncFrame(time:number,force=false){if(!videoFrames.value.length)return;let next=0;videoFrames.value.forEach((f,i)=>{if(f.timestamp<=time+.05)next=i});if(force||next!==activeVideoFrameIndex.value){activeVideoFrameIndex.value=next;selectedIndex.value=null;draw()}}
function loadedMetadata(){if(videoRef.value?.videoWidth){imageSize.value={width:videoRef.value.videoWidth,height:videoRef.value.videoHeight};updateSize()}syncFrame(videoRef.value?.currentTime??0,true)}
function toggleLabel(label:string){selectedIndex.value=null;selectedLabels.value=selectedLabels.value.includes(label)?selectedLabels.value.filter((x)=>x!==label):[...selectedLabels.value,label]}
function toggleAll(){selectedIndex.value=null;selectedLabels.value=selectedLabels.value.length===labels.value.length?[]:[...labels.value]}
function selectObject(i:number){selectedIndex.value=selectedIndex.value===i?null:i}
function setZoom(v:number){if(v===1){panOffset.x=0;panOffset.y=0}zoom.value=Math.min(3,Math.max(.35,Number(v.toFixed(2))))}
function wheel(e:WheelEvent){if(!mediaCanvas.value)return;setZoom(zoom.value+(e.deltaY<0?.1:-.1))}
function startPan(e:PointerEvent){if(e.button!==0||!viewportRef.value)return;const target=e.target as HTMLElement;if(isVideo.value&&target.closest('video')){const rect=target.getBoundingClientRect();if(e.clientY-rect.top>rect.height-52)return}panStart={x:e.clientX,y:e.clientY,left:panOffset.x,top:panOffset.y,moved:false};isPanning.value=true;viewportRef.value.setPointerCapture(e.pointerId)}
function movePan(e:PointerEvent){if(!panStart||!viewportRef.value)return;const dx=e.clientX-panStart.x,dy=e.clientY-panStart.y;if(Math.abs(dx)>3||Math.abs(dy)>3)panStart.moved=true;panOffset.x=panStart.left+dx;panOffset.y=panStart.top+dy}
function updateHover(e:PointerEvent){const canvas=canvasRef.value;if(!canvas||panStart||!imageSize.value.width){hoveredIndex.value=null;hoverTip.visible=false;return}const rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*imageSize.value.width,y=(e.clientY-rect.top)/rect.height*imageSize.value.height;const hit=[...visibleIndexes.value].reverse().find((index)=>{const [x1,y1,x2,y2]=activeObjects.value[index].bbox;return x>=x1&&x<=x2&&y>=y1&&y<=y2});hoveredIndex.value=hit??null;if(hit===undefined){hoverTip.visible=false;return}const viewport=viewportRef.value?.getBoundingClientRect();if(!viewport)return;hoverTip.x=Math.max(8,Math.min(viewport.width-248,e.clientX-viewport.left+14));hoverTip.y=Math.max(8,Math.min(viewport.height-142,e.clientY-viewport.top+14));hoverTip.visible=true;draw()}
function pointerMove(e:PointerEvent){updateHover(e);movePan(e)}
function clearHover(){if(!panStart){hoveredIndex.value=null;hoverTip.visible=false;draw()}}
function endPan(e:PointerEvent){if(viewportRef.value?.hasPointerCapture(e.pointerId))viewportRef.value.releasePointerCapture(e.pointerId);panStart=null;isPanning.value=false}
function exportCanvas(){if(!mediaCanvas.value)return;const out=document.createElement('canvas');out.width=mediaCanvas.value.width;out.height=mediaCanvas.value.height;const ctx=out.getContext('2d');if(!ctx)return;drawScene(ctx,{width:out.width,height:out.height},true);out.toBlob((b)=>{if(!b)return;const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`${fileName.value.replace(/\.[^.]+$/,'')||'annotation'}-annotated.png`;a.click();URL.revokeObjectURL(a.href)},'image/png')}
watch([()=>displayOptions.boxes,()=>displayOptions.labels,()=>displayOptions.confidence,()=>displayOptions.details,()=>displayOptions.maskFill,()=>displayOptions.maskEdge,()=>displayOptions.pose,()=>displayOptions.hands,selectedIndex,selectedLabels,activeVideoFrameIndex],draw)
onMounted(()=>{if(viewportRef.value){resizeObserver=new ResizeObserver(updateSize);resizeObserver.observe(viewportRef.value)}void health();healthTimer=window.setInterval(health,5000)})
onBeforeUnmount(()=>{requestController?.abort();revokeVideo();resizeObserver?.disconnect();if(healthTimer)window.clearInterval(healthTimer);if(analysisTimer)window.clearInterval(analysisTimer)})
</script>

<template>
<div class="app-shell"><header class="topbar"><div class="brand"><span class="brand-mark"><Aim/></span><div><h1>大模型识别</h1><p>GROUNDING DINO + SAM2 + RTMPOSE · OPENVINO LOCAL</p></div></div><div v-if="healthNotice" class="health-notice" role="status">{{healthNotice}}</div><div class="runtime-badge"><el-switch v-model="displayOptions.pose" size="small" active-text="姿态" inactive-text="姿态" :disabled="!mediaCanvas"/><span class="status-dot" :class="runtimeState"/>{{runtimeLabel}}</div></header>
<main class="workspace"><aside class="control-panel"><div class="panel-scroll"><section class="control-section"><div class="section-heading"><span class="step">01</span><h2>媒体输入</h2></div><el-upload v-if="!selectedFile" ref="uploadRef" class="media-upload" drag :auto-upload="false" :limit="1" accept="image/*,video/*" :show-file-list="false" :on-change="onChange" :on-exceed="onExceed"><el-icon class="upload-icon"><UploadFilled/></el-icon><div class="upload-title">图片 / 视频</div><div class="upload-meta">点击选择或拖放至此处<br>JPG PNG ≤20MB · MP4 AVI ≤100MB</div></el-upload><div v-else class="selected-media"><img v-if="thumbnailUrl" :src="thumbnailUrl" class="media-thumbnail" alt="媒体预览"/><div class="media-file-copy"><div class="file-type"><el-icon><VideoCamera v-if="isVideo"/><PictureFilled v-else/></el-icon>{{isVideo?'VIDEO / KEYFRAMES':'IMAGE'}}</div><strong>{{fileName}}</strong><span>{{imageSize.width}} × {{imageSize.height}} px</span></div><el-button class="remove-media" text :icon="Close" @click="clearMedia"/></div></section>
<section class="control-section prompt-section"><div class="section-heading"><span class="section-mark"/><h2>灵活提示</h2></div><div class="mode-list"><button :class="{active:promptMode==='universal'}" :disabled="loading" @click="changeMode('universal')"><span class="radio-dot"/>无需提示<small>全面候选检测</small></button><button :class="{active:promptMode==='text'}" :disabled="loading" @click="changeMode('text')"><span class="radio-dot"/>文本提示</button><button :class="{active:promptMode==='referring'}" :disabled="loading" @click="changeMode('referring')"><span class="radio-dot"/>指代提示</button></div><el-input v-if="promptMode!=='universal'" v-model="textPrompt" type="textarea" :rows="3" maxlength="160" show-word-limit/><p v-else class="prompt-hint">无需填写文本，本地候选词表覆盖人物、球类、车辆、道路、植被及建筑等常见主体。</p></section><section class="control-section local-note"><VideoCamera/><p>视频按约 3 秒间隔抽取关键帧，时长越长采样帧越多；播放器拖动时切换最近关键帧。</p></section></div><div class="action-area"><el-button v-if="loading" class="cancel-button" :loading="true" @click="cancelAnalysis">{{loadingDetail}}</el-button><el-button v-else class="analyze-button" type="primary" :icon="Search" :disabled="!canAnalyze" @click="runAnalysis">开始分析</el-button></div></aside>
<section class="visual-workspace"><div class="summary-ribbon"><span>输出反馈</span><p>{{response?.summary||'分析完成后显示本地模型摘要'}}</p><span v-if="response" class="task-mark">TASK {{response.task_id.slice(0,8)}}</span></div><div class="preview-toolbar"><div class="media-title"><span class="media-kind">{{isVideo?'VIDEO':'IMAGE'}}</span><strong>{{fileName||'媒体预览'}}</strong><span v-if="frameLabel" class="frame-mark">{{frameLabel}}</span></div><div class="toolbar-actions"><el-popover placement="bottom-end" :width="250" trigger="click"><template #reference><el-button text :icon="Setting" :disabled="!mediaCanvas">显示选项</el-button></template><div class="display-options"><h3>标注图层</h3><el-checkbox v-model="displayOptions.boxes">显示矩形框</el-checkbox><el-checkbox v-model="displayOptions.labels">显示类别名称</el-checkbox><el-checkbox v-model="displayOptions.confidence">显示置信度</el-checkbox><el-checkbox v-model="displayOptions.details">显示更多信息</el-checkbox><el-checkbox v-model="displayOptions.maskFill">显示分割填充</el-checkbox><el-checkbox v-model="displayOptions.maskEdge">显示分割边界</el-checkbox><p>关闭“显示更多信息”后，悬停标注框仍可查看完整信息。人物会显示真实 COCO 17 点；本地尚未配置手部姿态权重。</p></div></el-popover><el-button text :icon="ZoomOut" :disabled="!mediaCanvas" @click="setZoom(zoom-.1)"/><span>{{Math.round(zoom*100)}}%</span><el-button text :icon="ZoomIn" :disabled="!mediaCanvas" @click="setZoom(zoom+.1)"/><el-button text :icon="FullScreen" :disabled="!mediaCanvas" @click="setZoom(1)"/><el-button text :icon="RefreshRight" :disabled="!mediaCanvas" @click="draw"/><el-button text :icon="Download" :disabled="!mediaCanvas||loading" @click="exportCanvas"/></div></div>
<div ref="viewportRef" class="canvas-viewport" :class="{panning:isPanning}" @wheel.prevent="wheel" @pointerdown="startPan" @pointermove="pointerMove" @pointerleave="clearHover" @pointerup="endPan" @pointercancel="endPan"><div v-if="mediaCanvas" class="stage-space" :style="stageSpaceStyle"><div class="canvas-stage" :style="stageStyle"><video v-if="isVideo&&videoUrl" ref="videoRef" class="media-video" :src="videoUrl" :style="mediaStyle" controls playsinline preload="metadata" @loadedmetadata="loadedMetadata" @timeupdate="syncFrame(videoRef?.currentTime??0)" @seeked="syncFrame(videoRef?.currentTime??0,true)"/><canvas ref="canvasRef" :class="{'video-overlay':isVideo}" :style="mediaStyle"/></div></div><div v-else class="empty-canvas"><Aim/><strong>{{previewLoading?'正在解析媒体':'等待媒体文件'}}</strong></div><div v-if="mediaCanvas" class="pan-tip">{{isVideo?'原生播放控制 · 导出当前播放帧':'滚轮缩放 · 按住左键拖动'}}</div><div v-if="hoverTip.visible&&hoveredObject" class="annotation-tooltip" :style="{left:`${hoverTip.x}px`,top:`${hoverTip.y}px`}"><strong>{{hoveredObject.label}} <b>{{Math.round(hoveredObject.score*100)}}%</b></strong><span>{{hoveredObject.description}}</span><span v-if="hoveredObject.caption">描述：{{hoveredObject.caption}}</span><span v-if="hoveredObject.ocr_text">文字：{{hoveredObject.ocr_text}}</span><span v-if="hoveredObject.keypoints.length===17">人体 17 点：已识别</span><span v-if="hoveredObject.hand_keypoints.length">手部 2D：已识别</span></div><div v-if="loading" class="analysis-overlay" aria-live="polite"><span class="analysis-spinner"/><strong>正在转换图片并执行目标检测</strong><span>{{loadingDetail}}</span></div></div></section>
<aside class="result-panel"><div class="result-header"><div><span class="eyebrow">02 ANALYSIS RESULT</span><h2>分析结果</h2></div><span class="result-count" :class="{processing:loading}">{{loading?'处理中':`${activeObjects.length} 个`}}</span></div><div class="result-status">{{loading?'正在推理，请稍候':response?(isVideo?frameLabel:'识别完成，可筛选或独显'):'等待分析任务'}}</div><div v-if="loading" class="result-skeleton" aria-label="正在加载分析结果"><span/><span/><span/><span/></div><template v-else-if="response"><section class="summary-section"><span>内容摘要</span><p>{{response.summary}}</p></section><section class="result-section"><div class="section-title"><h3>语义标签</h3><span>{{labels.length}}</span></div><div class="label-list"><button @click="toggleAll">ALL <em>{{activeObjects.length}}</em></button><button v-for="label in labels" :key="label" :class="{active:selectedLabels.includes(label)}" @click="toggleLabel(label)">{{label}} <em>{{activeObjects.filter((x)=>x.label===label).length}}</em></button></div></section><section class="result-section spatial-section"><div class="section-title"><h3>空间标注</h3><span>{{activeObjects.length}}</span></div><div class="object-list"><button v-for="(item,index) in activeObjects" :key="`${activeVideoFrameIndex}-${index}`" class="object-card" :class="{selected:selectedIndex===index,muted:!selectedLabels.includes(item.label)}" @click="selectObject(index)"><i :style="{background:COLOR_CSS[index%COLOR_CSS.length]}"/><strong>{{item.label}}</strong><b>{{Math.round(item.score*100)}}%</b><small>[{{item.bbox.map((v)=>Math.round(v)).join(', ')}}]</small></button></div></section></template><div v-else class="empty-results"><Search/><strong>暂无识别结果</strong></div></aside></main></div>
</template>

